from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.procedure import db_markers
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console


def set_teb_default_values():
    db_markers.add_required_parameters()
    db_markers.add_default_teb_values()


@log_function_status_to_console(msg="Collect basic test case info", log_hierarchy=2)
@log_debug_function_info()
def collect_basic_test_case_info():
    db_markers.add_execution_date()
    db_markers.add_tester_user_name()
    db_markers.add_procedure_name()
    db_markers.add_test_case_name()
    db_markers.add_test_line()
    db_markers.add_test_line_owner()
    db_markers.add_test_line_type()
    db_markers.add_test_line_maintainers()
    db_markers.add_lab_location()
    if tc.is_feature_enabled("add_results_to_coop"):
        db_markers.add_coop_test_case_info()


@log_function_status_to_console(msg="Collect BTS version", log_hierarchy=2)
@log_debug_function_info()
def collect_bts_version():
    bts = perf.tl.main_bts
    bts_info = bts.collect_info()
    db_markers.add_bts_version(bts_sw_version=bts_info['sw_version'],
                               bts_release=bts_info['sw_release'])


@log_function_status_to_console(msg="Collect CORE version", log_hierarchy=2)
@log_debug_function_info()
def collect_core_version():
    core_info = perf.tl.core.get_version()
    db_markers.add_core_version(core_sw_version=core_info['sw_version'])


@log_function_status_to_console(msg="Collect UE version", log_hierarchy=2)
@log_debug_function_info()
def collect_ue_version():
    ue_info = perf.tl.ue.collect_info()
    db_markers.add_ue_version(ue_sw_version=ue_info['sw_version'], ue_type=ue_info['ue_type'])


def add_uptime_before_test_for_all_btss():
    for bts in tc.required_btss():
        uptime = bts.get_uptime(from_file=True)
        db_markers.add_bts_uptime_before_test(bts_uptime=uptime, device_name=bts.name)


def add_uptime_after_test_for_all_btss():
    for bts in tc.required_btss():
        uptime = bts.get_uptime(from_file=True)
        db_markers.add_bts_uptime_after_test(bts_uptime=uptime, device_name=bts.name)


@log_function_status_to_console(msg="Collect BTS cells info", log_hierarchy=2)
@log_debug_function_info()
def collect_bts_cells_info():
    for bts in tc.required_btss():
        if bts.ems:
            cells_info = bts.get_bts_cells_info()
            db_markers.add_bts_cells_info(device_name=bts.name,
                                          cells_bandwidths=cells_info['cells_bandwidths'],
                                          nr_of_cells=cells_info['nr_of_cells'])


@log_function_status_to_console(msg="Collect BTS RRH info", log_hierarchy=2)
@log_debug_function_info()
def collect_rrh_info():
    if perf.tl.ue.executor.name == "RTG":
        used_rrh_types = perf.tl.ue.get_used_rrhs()
        if used_rrh_types:
            db_markers.add_bts_used_rrhs(used_rrh_types)


@log_function_status_to_console(msg="Collect BTS HW info", log_hierarchy=2, ignore_exception=True)
@log_debug_function_info()
def collect_bts_hw_info():
    for bts in tc.required_btss():
        if getattr(bts, 'bts', None):
            bts_hw_code = bts.get_bts_hardware_product_code().replace('\x00', '')
            bts_modules = bts.get_modules()
            db_markers.add_bts_hw_info(device_name=bts.name, bts_hw_code=bts_hw_code, bts_modules=bts_modules)
